toad_implementation.code_blueprint:
canvas {
  size: 800px 920px;
  fill: #FFFDF0;
  font-family: "Fredoka One, cursive";
}

>bubblegum = #FF3366;
>poolCyan = #00D4FF;
>limeGreen = #70D600;
>sunYellow = #FFD000;
>darkNavy = #1E1B4B;

rect #headerBanner {
  at: top center of canvas offset 0px 40px;
  size: 720px 140px;
  fill: >sunYellow;
  stroke: >darkNavy;
  stroke-width: 5px;
  radius: 36px;
}

text #mainTitle {
  at: center of #headerBanner offset 0px -10px;
  content: "TOBO - LAND!";
  font-size: 52px;
  font-weight: 900;
  color: >bubblegum;
}

text #mainSubtitle {
  at: below #mainTitle offset 8px;
  content: "THE BIGGEST PLAYGROUND IN THE CITY";
  font-size: 15px;
  font-weight: 700;
  color: >darkNavy;
}

rect #card1Shadow {
  at: below #headerBanner offset 36px 6px;
  size: 340px 300px;
  fill: >darkNavy;
  radius: 28px;
}

rect #card1 {
  at: below #headerBanner offset 30px 0px;
  size: 340px 300px;
  fill: >poolCyan;
  stroke: >darkNavy;
  stroke-width: 5px;
  radius: 28px;
}

circle #iconBubble1 {
  at: top center of #card1 offset 0px 36px;
  size: 90px;
  fill: #FFFFFF;
}

text #iconEmoji1 {
  at: center of #iconBubble1;
  content: "★";
  font-size: 48px;
  color: >sunYellow;
}

text #card1Title {
  at: below #iconBubble1 offset 24px;
  content: "TRAMPOLIN";
  font-size: 26px;
  font-weight: 900;
  color: #FFFFFF;
}

text #card1Sub {
  at: below #card1Title offset 8px;
  content: "40 XXL-Sprungfelder!";
  font-size: 14px;
  font-weight: 700;
  color: >darkNavy;
}

rect #safetyBadge {
  at: bottom center of canvas offset 0px -40px;
  size: 460px 56px;
  fill: >limeGreen;
  stroke: >darkNavy;
  stroke-width: 4px;
  radius: 28px;
}

text #safetyText {
  at: center of #safetyBadge;
  content: "✔ TÜV-GEPRÜFT • SOFTSCHUTZ AN ALLEN ECKEN";
  font-size: 13px;
  font-weight: 900;
  color: >darkNavy;
}
